var cyberpunksColorPalettes = {{ cyberpunks_color_palettes_json|raw }};
var cyberpunksOptionValueFieldKeys = {
{% for field in cyberpunks_option_value_custom_field_defs %}
  '{{ field.field_key }}': {{ field.field_id }}{% if not loop.last %},{% endif %}
{% endfor %}
};
var cyberpunksDefaultModeKeys = ['image', 'icon', 'color'];
var cyberpunksPaletteModeKeys = ['swatch_color', 'model_color'];

function cyberpunksGetValuesMode() {
  return $('input[name="cyberpunks_option_mode[values_mode]"]:checked').val() === 'color_palette' ? 'color_palette' : 'default';
}

function cyberpunksToggleColumns() {
  var mode = cyberpunksGetValuesMode();
  var showImage = mode === 'default' && $('#input-cyberpunks-show-image').is(':checked');
  $('.cyberpunks-image-column').toggle(showImage);

  {% for field in cyberpunks_option_value_custom_field_defs %}
  (function(fieldId, fieldKey) {
    var allowed = mode === 'color_palette' ? (cyberpunksPaletteModeKeys.indexOf(fieldKey) !== -1) : (cyberpunksDefaultModeKeys.indexOf(fieldKey) !== -1);
    var checked = $('#input-cyberpunks-show-field-' + fieldId).is(':checked');
    $('.cyberpunks-custom-field-column-' + fieldId).toggle(allowed && checked);
  })({{ field.field_id }}, '{{ field.field_key }}');
  {% endfor %}

  var hideAdd = mode === 'color_palette';
  $('#option-value tfoot .btn-primary').toggle(!hideAdd);
}

function cyberpunksApplyValuesModeUi(syncPalettes) {
  var mode = cyberpunksGetValuesMode();
  $('#cyberpunks-palette-settings').toggle(mode === 'color_palette');

  $('.cyberpunks-values-field-toggle').each(function() {
    var $label = $(this);
    var key = $label.data('field-key') || ($label.find('input').data('field-key') || '');
    var modes = $label.attr('data-modes') || $label.data('modes') || '';
    var allowed;

    if ($label.find('#input-cyberpunks-show-image').length) {
      allowed = mode === 'default';
    } else if (modes) {
      allowed = modes.split(',').indexOf(mode) !== -1;
    } else {
      allowed = mode === 'default' ? (cyberpunksDefaultModeKeys.indexOf(key) !== -1) : (cyberpunksPaletteModeKeys.indexOf(key) !== -1);
    }

    $label.toggle(allowed);

    if (!allowed) {
      $label.find('input[type="checkbox"]').prop('checked', false);
    }
  });

  if (mode === 'color_palette') {
    {% for field in cyberpunks_option_value_custom_field_defs %}
    {% if field.field_key in ['swatch_color', 'model_color'] %}
    $('#input-cyberpunks-show-field-{{ field.field_id }}').prop('checked', true);
    {% endif %}
    {% endfor %}
    $('#input-cyberpunks-show-image').prop('checked', false);

    if (syncPalettes) {
      cyberpunksSyncPaletteOptionValues();
    }
  }

  cyberpunksToggleColumns();
}

function cyberpunksSetOptionValueCustomField(row, fieldKey, value) {
  var fieldId = cyberpunksOptionValueFieldKeys[fieldKey];
  if (!fieldId) {
    return;
  }

  var $row = $('#option-value-row' + row);
  var $input = $row.find('[name="option_value[' + row + '][cyberpunks_custom_fields][' + fieldId + ']"]');
  if (!$input.length) {
    return;
  }

  if ($input.is(':checkbox')) {
    $input.filter(':checkbox').prop('checked', !!value && value !== '0');
  } else {
    $input.val(value);
  }
}

function cyberpunksUpdateOptionValueRow(row, color) {
  var $row = $('#option-value-row' + row);
  if (!$row.length || row === undefined || row === null || row === '') {
    return;
  }

  {% for language in languages %}
  $row.find('input[name="option_value[' + row + '][option_value_description][{{ language.language_id }}][name]"]').val(color.name || '');
  {% endfor %}
  $row.find('input[name="option_value[' + row + '][sort_order]"]').val(color.sort_order != null ? color.sort_order : 0);
  $row.find('input.cyberpunks-palette-color-id').val(String(color.color_id));
  cyberpunksSetOptionValueCustomField(row, 'swatch_color', color.swatch_color || '');
  cyberpunksSetOptionValueCustomField(row, 'model_color', color.model_color || color.swatch_color || '');
}

function cyberpunksSyncPaletteOptionValues() {
  if (cyberpunksGetValuesMode() !== 'color_palette') {
    return;
  }

  if (typeof option_value_row === 'undefined' || typeof addOptionValue !== 'function') {
    return;
  }

  var type = $('select[name=\'type\']').val();
  if (type != 'select' && type != 'radio' && type != 'checkbox' && type != 'image') {
    $('select[name=\'type\']').val('select').trigger('change');
  } else {
    $('select[name=\'type\']').trigger('change');
  }

  var selectedPaletteIds = $('.cyberpunks-option-palette-toggle:checked').map(function() {
    return parseInt($(this).val(), 10);
  }).get();

  var wanted = [];
  var wantedMap = {};

  cyberpunksColorPalettes.forEach(function(palette) {
    if (selectedPaletteIds.indexOf(parseInt(palette.palette_id, 10)) === -1) {
      return;
    }

    (palette.colors || []).forEach(function(color) {
      var colorId = parseInt(color.color_id, 10);
      if (!colorId || !color.name || wantedMap[colorId]) {
        return;
      }
      wanted.push(color);
      wantedMap[colorId] = true;
    });
  });

  var existingByColor = {};

  $('#option-value tbody tr').each(function() {
    var $row = $(this);
    var rowId = ($row.attr('id') || '').replace('option-value-row', '');
    var colorId = parseInt($row.find('input.cyberpunks-palette-color-id').val(), 10) || 0;

    if (colorId > 0 && wantedMap[colorId]) {
      if (existingByColor[colorId] !== undefined) {
        $row.remove();
        return;
      }
      existingByColor[colorId] = rowId;
    } else {
      // Palette mode: drop unlinked rows and colors no longer in selected palettes.
      $row.remove();
    }
  });

  wanted.forEach(function(color) {
    var colorId = parseInt(color.color_id, 10);
    if (existingByColor[colorId] !== undefined) {
      cyberpunksUpdateOptionValueRow(existingByColor[colorId], color);
      return;
    }

    var row = option_value_row;
    addOptionValue();
    cyberpunksUpdateOptionValueRow(row, color);
  });

  cyberpunksToggleColumns();
}

$('#input-cyberpunks-show-image').on('change', cyberpunksToggleColumns);
{% for field in cyberpunks_option_value_custom_field_defs %}
$('#input-cyberpunks-show-field-{{ field.field_id }}').on('change', cyberpunksToggleColumns);
{% endfor %}
{% for field in cyberpunks_option_custom_fields %}
$('#input-cyberpunks-show-option-field-{{ field.field_id }}').on('change', function() {
  $('.cyberpunks-option-field-input-{{ field.field_id }}').toggle($(this).is(':checked'));
});
$('.cyberpunks-option-field-input-{{ field.field_id }}').toggle($('#input-cyberpunks-show-option-field-{{ field.field_id }}').is(':checked'));
{% endfor %}

$('input[name="cyberpunks_option_mode[values_mode]"]').on('change', function() {
  cyberpunksApplyValuesModeUi(true);
});

$(document).on('change', '.cyberpunks-option-palette-toggle', function() {
  if (cyberpunksGetValuesMode() === 'color_palette') {
    cyberpunksSyncPaletteOptionValues();
  }
});

cyberpunksApplyValuesModeUi(cyberpunksGetValuesMode() === 'color_palette');

$('#button-cyberpunks-sync-products').on('click', function() {
  var optionId = {{ cyberpunks_option_id|default(0) }};
  var $btn = $(this);
  var $alert = $('#cyberpunks-sync-products-alert');

  if (!optionId) {
    alert('{{ text_cyberpunks_sync_products_save_first|e('js') }}');
    return;
  }

  if (!confirm('{{ text_cyberpunks_sync_products_confirm|e('js') }}')) {
    return;
  }

  $btn.prop('disabled', true);
  $alert.hide().removeClass('alert-success alert-danger').empty();

  $.ajax({
    url: 'index.php?route=extension/module/cyberpunks_shop_option_fields/syncProducts&user_token={{ user_token }}&option_id=' + optionId,
    type: 'get',
    dataType: 'json',
    success: function(json) {
      if (json['error']) {
        $alert.addClass('alert alert-danger').text(json['error']).show();
        $btn.prop('disabled', false);
      } else if (json['success']) {
        $alert.addClass('alert alert-success').text(json['success']).show();
        if (json['reload']) {
          setTimeout(function() {
            window.location.reload();
          }, 700);
        } else {
          $btn.prop('disabled', false);
        }
      } else {
        $btn.prop('disabled', false);
      }
    },
    error: function(xhr, status, error) {
      $alert.addClass('alert alert-danger').text(error || status).show();
      $btn.prop('disabled', false);
    }
  });
});

